  function cleanCoordinatorName(raw) {
    return String(raw || "").replace(/\s*\[รอยืนยัน.*?\]\s*/g, "").trim();
  }

  function formatAdvisorWithCoordinator(siteOrArea, fallbackAdv) {
    const site =
      siteOrArea && typeof siteOrArea === "object"
        ? siteOrArea
        : (SCHED.fieldworkSites || []).find((x) => x.shortName === String(siteOrArea || ""));
    const adv = String(fallbackAdv || (site && site.advisors) || "-").trim();
    const staff = site ? cleanCoordinatorName(site.staffRef) : "";
    if (!staff) return adv;
    return `${adv} · ${tr("ผู้ประสานงาน", "Coordinator")}: ${staff}`;
  }

  /* ---------- Date & Time Helpers ---------- */
  function parseISODate(iso) {
    const [y, m, d] = String(iso).split("-").map(Number);
    return new Date(Date.UTC(y, m - 1, d));
  }

  function formatISODate(dt) {
    const y = dt.getUTCFullYear();
    const m = String(dt.getUTCMonth() + 1).padStart(2, "0");
    const d = String(dt.getUTCDate()).padStart(2, "0");
    return `${y}-${m}-${d}`;
  }

  function addDaysISO(iso, delta) {
    const dt = parseISODate(iso);
    dt.setUTCDate(dt.getUTCDate() + delta);
    return formatISODate(dt);
  }

  function formatThaiShortDate(iso, forceMonth) {
    const [y, m, d] = String(iso).split("-").map(Number);
    if (forceMonth || d === 1 || (m === 11 && d === 25) || (m === 12 && d === 30)) {
      return `${d} ${TH_MONTHS_SHORT[m]}${y === 2027 ? " 70" : ""}`;
    }
    return String(d);
  }

  function timeToMinutes(hhmm) {
    const [h, m] = String(hhmm || "09:00").split(":").map(Number);
    return (h || 0) * 60 + (m || 0);
  }

  function to12HourAmPm(hhmm) {
    const [hRaw, mRaw] = String(hhmm || "09:00").split(":").map(Number);
    const h = Number.isFinite(hRaw) ? hRaw : 9;
    const m = Number.isFinite(mRaw) ? mRaw : 0;
    const ampm = h >= 12 ? "PM" : "AM";
    const h12 = h % 12 === 0 ? 12 : h % 12;
    return `${String(h12).padStart(2, "0")}:${String(m).padStart(2, "0")} ${ampm}`;
  }

  function isoToUsDate(iso) {
    const [y, m, d] = String(iso).split("-");
    return `${m}/${d}/${y}`;
  }

  function setBtnLabel(btn, text) {
    if (!btn) return;
    const span = btn.querySelector ? btn.querySelector("[data-btn-label]") : null;
    if (span) span.textContent = text;
    else btn.textContent = text;
  }

  function copyTextWithFeedback(text, btn, doneLabel = "คัดลอกแล้ว ✓") {
    if (!navigator.clipboard) return;
    navigator.clipboard.writeText(text).then(() => {
      if (!btn) return;
      const span = btn.querySelector ? btn.querySelector("[data-btn-label]") : null;
      const prev = span ? span.textContent : btn.textContent;
      if (span) span.textContent = doneLabel;
      else btn.textContent = doneLabel;
      setTimeout(() => {
        if (span) span.textContent = prev;
        else btn.textContent = prev;
      }, 1500);
    });
  }

  function printWithCleanTitle(tempTitle) {
    document.body.classList.remove("print-students-mode", "print-disc-mode", "print-single-hsd-case");
    const prevTitle = document.title;
    if (tempTitle) document.title = tempTitle;
    window.print();
    if (tempTitle) {
      setTimeout(() => {
        document.title = prevTitle;
      }, 600);
    }
  }

  /* ---------- Client-Side Genuine OpenXML (.docx) Stored-ZIP Exporter (for Filtered Views) ---------- */
  const CRC32_TABLE = (() => {
    const tbl = new Uint32Array(256);
    for (let i = 0; i < 256; i++) {
      let c = i;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      tbl[i] = c >>> 0;
    }
    return tbl;
  })();

  function crc32Bytes(bytes) {
    let crc = 0xffffffff;
    for (let i = 0; i < bytes.length; i++) {
      crc = CRC32_TABLE[(crc ^ bytes[i]) & 0xff] ^ (crc >>> 8);
    }
    return (crc ^ 0xffffffff) >>> 0;
  }

  function buildStoredZipBlob(entries, mimeType) {
    const enc = new TextEncoder();
    const localParts = [];
    const centralParts = [];
    let offset = 0;

    entries.forEach((entry) => {
      const nameBytes = enc.encode(entry.name);
      const dataBytes = entry.bytes instanceof Uint8Array ? entry.bytes : enc.encode(String(entry.content || ""));
      const crc = crc32Bytes(dataBytes);
      const size = dataBytes.length;

      const local = new Uint8Array(30 + nameBytes.length);
      const lv = new DataView(local.buffer);
      lv.setUint32(0, 0x04034b50, true);
      lv.setUint16(4, 20, true);
      lv.setUint16(6, 0x0800, true); // UTF-8 filename flag
      lv.setUint16(8, 0, true); // STORE (uncompressed)
      lv.setUint16(10, 0, true);
      lv.setUint16(12, 0x5774, true);
      lv.setUint32(14, crc, true);
      lv.setUint32(18, size, true);
      lv.setUint32(22, size, true);
      lv.setUint16(26, nameBytes.length, true);
      lv.setUint16(28, 0, true);
      local.set(nameBytes, 30);

      const central = new Uint8Array(46 + nameBytes.length);
      const cv = new DataView(central.buffer);
      cv.setUint32(0, 0x02014b50, true);
      cv.setUint16(4, 20, true);
      cv.setUint16(6, 20, true);
      cv.setUint16(8, 0x0800, true);
      cv.setUint16(10, 0, true);
      cv.setUint16(12, 0, true);
      cv.setUint16(14, 0x5774, true);
      cv.setUint32(16, crc, true);
      cv.setUint32(20, size, true);
      cv.setUint32(24, size, true);
      cv.setUint16(28, nameBytes.length, true);
      cv.setUint16(30, 0, true);
      cv.setUint16(32, 0, true);
      cv.setUint16(34, 0, true);
      cv.setUint16(36, 0, true);
      cv.setUint32(38, 0, true);
      cv.setUint32(42, offset, true);
      central.set(nameBytes, 46);

      localParts.push(local, dataBytes);
      centralParts.push(central);
      offset += local.length + dataBytes.length;
    });

    const centralSize = centralParts.reduce((acc, b) => acc + b.length, 0);
    const eocd = new Uint8Array(22);
    const ev = new DataView(eocd.buffer);
    ev.setUint32(0, 0x06054b50, true);
    ev.setUint16(4, 0, true);
    ev.setUint16(6, 0, true);
    ev.setUint16(8, entries.length, true);
    ev.setUint16(10, entries.length, true);
    ev.setUint32(12, centralSize, true);
    ev.setUint32(16, offset, true);
    ev.setUint16(20, 0, true);

    return new Blob([...localParts, ...centralParts, eocd], { type: mimeType });
  }

  function escXml(str) {
    return String(str || "")
      .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function wRunXml(text, opts = {}) {
    const t = escXml(text);
    if (!t) return "";
    const rPr = [
      `<w:rFonts w:ascii="Sarabun" w:hAnsi="Sarabun" w:cs="Sarabun" w:eastAsia="Sarabun"/>`,
      opts.bold ? "<w:b/><w:bCs/>" : "",
      opts.color ? `<w:color w:val="${opts.color}"/>` : "",
      opts.sz ? `<w:sz w:val="${opts.sz}"/><w:szCs w:val="${opts.sz}"/>` : `<w:sz w:val="23"/><w:szCs w:val="23"/>`
    ].join("");
    return `<w:r><w:rPr>${rPr}</w:rPr><w:t xml:space="preserve">${t}</w:t></w:r>`;
  }

  function wParaXml(runsXml, spaceBefore = 60, spaceAfter = 100) {
    return `<w:p><w:pPr><w:spacing w:before="${spaceBefore}" w:after="${spaceAfter}" w:line="290" w:lineRule="auto"/></w:pPr>${runsXml}</w:p>`;
  }

  function domNodeToWordBlocks(rootNode) {
    const out = [];
    const extractCellText = (el) => {
      const clone = el.cloneNode(true);
      clone.querySelectorAll("textarea, button, svg, script, style").forEach((n) => n.remove());
      return clone.textContent.replace(/\s+/g, " ").trim();
    };
    const walk = (node) => {
      if (!node || node.nodeType !== 1) return;
      if (node.hidden || (node.classList && node.classList.contains("hsd-no-print"))) return;
      const tag = String(node.tagName || "").toUpperCase();
      if (tag === "SCRIPT" || tag === "STYLE" || tag === "BUTTON" || tag === "SVG" || tag === "TEXTAREA") return;
      if (tag === "H1" || tag === "H2") {
        out.push(wParaXml(wRunXml(node.textContent.trim(), { bold: true, sz: 30, color: "002D72" }), 220, 100));
      } else if (tag === "H3" || tag === "H4") {
        out.push(wParaXml(wRunXml(node.textContent.trim(), { bold: true, sz: 25, color: "0F766E" }), 160, 80));
      } else if (tag === "H5" || tag === "H6") {
        out.push(wParaXml(wRunXml(node.textContent.trim(), { bold: true, sz: 23, color: "1E293B" }), 120, 60));
      } else if (tag === "P" || tag === "BLOCKQUOTE" || tag === "FIGCAPTION") {
        const txt = node.textContent.replace(/\s+/g, " ").trim();
        if (txt) out.push(wParaXml(wRunXml(txt, { sz: tag === "FIGCAPTION" ? 19 : 23, color: tag === "FIGCAPTION" ? "475569" : "162238" }), 40, 100));
      } else if (tag === "UL" || tag === "OL") {
        const isOrdered = tag === "OL";
        [...node.children].forEach((li, idx) => {
          if (String(li.tagName || "").toUpperCase() !== "LI") return;
          const prefix = isOrdered ? `${idx + 1}. ` : "• ";
          const txt = li.textContent.replace(/\s+/g, " ").trim();
          if (txt) out.push(wParaXml(wRunXml(prefix + txt, { sz: 23 }), 30, 60));
        });
      } else if (tag === "TABLE") {
        const rows = [...node.querySelectorAll("tr")];
        if (!rows.length) return;
        const trXml = rows
          .map((tr, rIdx) => {
            const cells = [...tr.querySelectorAll("th, td")];
            if (!cells.length) return "";
            const isHead = rIdx === 0 || cells.every((c) => String(c.tagName || "").toUpperCase() === "TH");
            const tcXml = cells
              .map((cell) => {
                const txt = extractCellText(cell);
                const shd = isHead ? `<w:shd w:val="clear" w:color="auto" w:fill="E8EEF7"/>` : "";
                return `<w:tc><w:tcPr>${shd}<w:tcMar><w:top w:w="80" w:type="dxa"/><w:bottom w:w="80" w:type="dxa"/><w:left w:w="110" w:type="dxa"/><w:right w:w="110" w:type="dxa"/></w:tcMar></w:tcPr>${wParaXml(
                  wRunXml(txt, { bold: isHead, sz: 20, color: isHead ? "00245C" : "162238" }),
                  20,
                  20
                )}</w:tc>`;
              })
              .join("");
            return `<w:tr>${tcXml}</w:tr>`;
          })
          .join("");
        out.push(
          `<w:tbl><w:tblPr><w:tblW w:w="5000" w:type="pct"/><w:tblBorders>` +
            `<w:top w:val="single" w:sz="6" w:space="0" w:color="CBD5E1"/>` +
            `<w:left w:val="single" w:sz="6" w:space="0" w:color="CBD5E1"/>` +
            `<w:bottom w:val="single" w:sz="6" w:space="0" w:color="CBD5E1"/>` +
            `<w:right w:val="single" w:sz="6" w:space="0" w:color="CBD5E1"/>` +
            `<w:insideH w:val="single" w:sz="4" w:space="0" w:color="CBD5E1"/>` +
            `<w:insideV w:val="single" w:sz="4" w:space="0" w:color="CBD5E1"/>` +
            `</w:tblBorders></w:tblPr>${trXml}</w:tbl>`
        );
      } else {
        [...node.children].forEach(walk);
      }
    };
    [...rootNode.children].forEach(walk);
    return out.join("");
  }

  function downloadHtmlAsGenuineDocx(title, subtitle, htmlString, filename) {
    const holder = document.createElement("div");
    holder.innerHTML = htmlString;
    const bodyXml =
      wParaXml(wRunXml(title, { bold: true, sz: 34, color: "002D72" }), 0, 80) +
      (subtitle ? wParaXml(wRunXml(subtitle, { bold: true, sz: 21, color: "475569" }), 0, 180) : "") +
      domNodeToWordBlocks(holder) +
      `<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1020" w:right="1020" w:bottom="1020" w:left="1020"/></w:sectPr>`;

    const entries = [
      {
        name: "[Content_Types].xml",
        content:
          `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>` +
          `<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">` +
          `<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>` +
          `<Default Extension="xml" ContentType="application/xml"/>` +
          `<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>` +
          `</Types>`
      },
      {
        name: "_rels/.rels",
        content:
          `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>` +
          `<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">` +
          `<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>` +
          `</Relationships>`
      },
      {
        name: "word/document.xml",
        content:
          `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>` +
          `<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>${bodyXml}</w:body></w:document>`
      }
    ];

    const blob = buildStoredZipBlob(
      entries,
      "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
    );
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename.endsWith(".docx") ? filename : `${filename}.docx`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 2500);
  }

  /* ---------- Student Portrait Loader ---------- */
  function studentInitials(s) {
    const parts = String(s.name || "").trim().split(/\s+/);
    const a = parts[0] ? [...parts[0]][0] : "น";
    const b = parts[1] ? [...parts[1]][0] : "";
    return (a + b).toUpperCase();
  }

  const photoObserver = "IntersectionObserver" in window
    ? new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting) return;
          photoObserver.unobserve(entry.target);
          mountStudentPhoto(entry.target);
        });
      }, { rootMargin: "220px" })
    : null;

  function mountStudentPhoto(box) {
    const localPhoto = box.dataset.localPhoto || "";
    const sid = box.dataset.studentId || "";
    const pid = box.dataset.photoId || "";
    const initials = box.dataset.initials || "นศ";
    const sLabel = box.dataset.studentName || initials;
    if (!localPhoto && !sid && !pid) {
      box.innerHTML = `<span class="avatar-monogram" title="${escapeHtml(sLabel)}">${escapeHtml(initials)}</span>`;
      return;
    }
    const img = document.createElement("img");
    img.alt = box.dataset.studentName || "รูปถ่าย";
    img.loading = "lazy";
    img.decoding = "async";
    if (localPhoto || sid) {
      img.src = localPhoto || `assets/photos/${encodeURIComponent(sid)}.jpg`;
      img.onerror = () => {
        if (pid && !img.dataset.triedDrive) {
          img.dataset.triedDrive = "1";
          img.referrerPolicy = "no-referrer";
          img.src = `https://drive.google.com/thumbnail?id=${encodeURIComponent(pid)}&sz=w320`;
          return;
        }
        box.innerHTML = `<span class="avatar-monogram" title="${escapeHtml(sLabel)}">${escapeHtml(initials)}</span>`;
      };
    } else {
      img.referrerPolicy = "no-referrer";
      img.src = `https://drive.google.com/thumbnail?id=${encodeURIComponent(pid)}&sz=w320`;
      img.onerror = () => {
        box.innerHTML = `<span class="avatar-monogram" title="${escapeHtml(sLabel)}">${escapeHtml(initials)}</span>`;
      };
    }
    box.replaceChildren(img);
  }

  function getStaffCoordinatorInfo(siteOrArea) {
    const site =
      siteOrArea && typeof siteOrArea === "object"
        ? siteOrArea
        : (SCHED.fieldworkSites || []).find((x) => x.shortName === String(siteOrArea || ""));
    if (!site) return null;
    const raw = cleanCoordinatorName(site.staffRef || "");
    const m = raw.match(/^(.+?)\s*\((.+?)\)$/);
    const firstName = site.staffFirstName || (m ? m[1].trim() : raw);
    const nickname = site.staffNickname || (m ? m[2].trim() : raw);
    const hasLocal = Boolean(site.staffHasLocalPhoto);
    const photoId = site.staffPhotoId || "";
    const localSrc = hasLocal ? `assets/photos/staff_${encodeURIComponent(site.id)}.jpg` : "";
    const initials = site.staffInitials || (firstName.replace(/^คุณ/, "").slice(0, 2) || "จนท");
    return {
      site,
      siteId: site.id,
      firstName,
      nickname,
      displayFull: raw || `${firstName} (${nickname})`,
      hasPhoto: Boolean(hasLocal || photoId),
      localSrc,
      photoId,
      initials
    };
  }

  function zoomStaffPhoto(siteOrArea) {
    const info = getStaffCoordinatorInfo(siteOrArea);
    if (!info || !info.hasPhoto) return;
    const caption = `${info.nickname} (${info.firstName}) · เจ้าหน้าที่ประสานงานประจำพื้นที่ ${info.siteId}. ${info.site.shortName} (${info.site.hospital} ${info.site.province})`;
    const src = info.localSrc || `https://drive.google.com/thumbnail?id=${encodeURIComponent(info.photoId)}&sz=w1000`;
    openLightbox(src, caption);
    if (info.photoId) {
      const hdUrl = `https://drive.google.com/thumbnail?id=${encodeURIComponent(info.photoId)}&sz=w1200`;
      const pre = new Image();
      pre.referrerPolicy = "no-referrer";
      pre.onload = () => {
        const lb = $("imageLightbox");
        const lbImg = $("lightboxImg");
        if (lb && !lb.hidden && lbImg && pre.naturalWidth >= 180) {
          lbImg.referrerPolicy = "no-referrer";
          lbImg.src = hdUrl;
        }
      };
      pre.src = hdUrl;
    }
  }

  function renderStaffCoordinatorCardElement(siteOrArea) {
    const info = getStaffCoordinatorInfo(siteOrArea);
    if (!info) return document.createDocumentFragment();
    const { site, siteId } = info;
    const card = make("article", null, `student-card is-interactive is-staff-card card-site-${siteId} chip-site-${siteId}`);
    card.tabIndex = 0;
    card.setAttribute("role", "button");
    card.setAttribute("aria-label", `${info.nickname} (${info.firstName}) เจ้าหน้าที่ประสานงานพื้นที่ ${site.shortName}`);

    const portraitWrap = make("div", null, "student-portrait-wrap");
    const portrait = make("div", null, `student-portrait${state.showPhotos ? "" : " compact-avatar"}`);
    if (info.localSrc) portrait.dataset.localPhoto = info.localSrc;
    if (info.photoId) portrait.dataset.photoId = info.photoId;
    portrait.dataset.initials = info.initials;
    portrait.dataset.studentName = info.displayFull;
    portrait.innerHTML = `<span class="avatar-monogram">${escapeHtml(info.initials)}</span>`;
    if (state.showPhotos && info.hasPhoto) {
      if (photoObserver) photoObserver.observe(portrait);
      else mountStudentPhoto(portrait);
    }
    portraitWrap.appendChild(portrait);

    if (state.showPhotos && info.hasPhoto) {
      const zoomCornerBtn = make("button", null, "portrait-zoom-corner-btn");
      zoomCornerBtn.type = "button";
      zoomCornerBtn.title = tr("ขยายรูปถ่ายพี่เจ้าหน้าที่ (Zoom In)", "Zoom in coordinator photo");
      zoomCornerBtn.setAttribute("aria-label", tr(`ขยายรูปถ่าย ${info.nickname}`, `Zoom photo of ${info.nickname}`));
      zoomCornerBtn.innerHTML = `<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="11" cy="11" r="7"/><line x1="21" y1="21" x2="16.65" y2="16.65"/><line x1="11" y1="8" x2="11" y2="14"/><line x1="8" y1="11" x2="14" y2="11"/></svg>`;
      zoomCornerBtn.addEventListener("click", (ev) => {
        ev.stopPropagation();
        zoomStaffPhoto(site);
      });
      portraitWrap.appendChild(zoomCornerBtn);
    }

    card.appendChild(portraitWrap);
    card.appendChild(make("h3", info.nickname, "stu-card-lead"));
    card.appendChild(make("p", `(${info.firstName})`, "stu-card-paren"));
    card.appendChild(make("p", tr("ผู้ประสานงานประจำพื้นที่", "Site Coordinator"), "sid-mono staff-role-mono"));

    const pillWrap = make("div", null, "s-area area-sub-pill-wrap");
    pillWrap.innerHTML = `<span class="area-sub-pill area-site-${siteId}"><i class="area-dot"></i>${siteId}. ${escapeHtml(site.shortName)}</span>`;
    card.appendChild(pillWrap);
    card.appendChild(make("p", `${site.hospital}`, "disc-line"));

    const hint = make(
      "span",
      info.hasPhoto ? tr("ขยายรูปถ่าย ↗", "Zoom Photo ↗") : tr("ผู้ประสานงานกลุ่ม", "Coordinator"),
      "student-quick-hint"
    );
    card.appendChild(hint);

    card.addEventListener("click", () => {
      if (info.hasPhoto) zoomStaffPhoto(site);
      else setSyncedFieldworkArea(site.shortName);
    });
    card.addEventListener("keydown", (ev) => {
      if (ev.key === "Enter" || ev.key === " ") {
        ev.preventDefault();
        if (info.hasPhoto) zoomStaffPhoto(site);
      }
    });
    return card;
  }

  function renderStaffHeaderBadge(siteOrArea, compactPrint = false) {
    const info = getStaffCoordinatorInfo(siteOrArea);
    if (!info) return null;
    const wrap = make("div", null, `staff-coord-badge${info.hasPhoto ? " is-zoomable" : ""}${compactPrint ? " is-print-badge" : ""}`);
    const av = make("div", null, "staff-coord-avatar student-portrait");
    if (info.localSrc) av.dataset.localPhoto = info.localSrc;
    if (info.photoId) av.dataset.photoId = info.photoId;
    av.dataset.initials = info.initials;
    av.dataset.studentName = info.displayFull;
    av.innerHTML = `<span class="avatar-monogram">${escapeHtml(info.initials)}</span>`;
    if (info.hasPhoto) mountStudentPhoto(av);

    const meta = make("div", null, "staff-coord-meta");
    meta.innerHTML =
      `<span class="staff-coord-kicker">${escapeHtml(tr("ผู้ประสานงานพื้นที่", "Coordinator"))}</span>` +
      `<strong class="staff-coord-lead">${escapeHtml(info.nickname)}</strong>` +
      `<span class="staff-coord-sub">${escapeHtml(info.firstName)}</span>`;
    wrap.append(av, meta);
    if (info.hasPhoto) {
      wrap.title = tr("คลิกเพื่อขยายรูปถ่ายผู้ประสานงาน", "Click to zoom coordinator photo");
      wrap.addEventListener("click", (ev) => {
        ev.stopPropagation();
        zoomStaffPhoto(info.site);
      });
    }
    return wrap;
  }

  function renderStaffMiniChip(siteOrArea) {
    const info = getStaffCoordinatorInfo(siteOrArea);
    if (!info) return null;
    const chip = make("button", null, `gsorter-stu-chip is-staff-mini-chip chip-site-${info.siteId}`);
    chip.type = "button";
    chip.title = `${info.displayFull} · ผู้ประสานงานประจำพื้นที่ ${info.site.shortName}`;
    const av = make("span", null, "gsorter-chip-avatar");
    if (info.localSrc) {
      const img = document.createElement("img");
      img.src = info.localSrc;
      img.alt = "";
      img.loading = "lazy";
      img.decoding = "async";
      img.onerror = () => {
        av.textContent = info.initials;
      };
      av.appendChild(img);
    } else {
      av.textContent = info.initials;
    }
    const txt = make("span", null, "gsorter-chip-txt");
    txt.innerHTML = `<strong class="chip-lead">${escapeHtml(info.nickname)}</strong><small class="chip-paren">(${escapeHtml(info.firstName)} · ผู้ประสานงาน)</small>`;
    chip.append(av, txt);
    chip.addEventListener("click", (ev) => {
      ev.stopPropagation();
      if (info.hasPhoto) zoomStaffPhoto(info.site);
    });
    return chip;
  }

