    card.appendChild(make("p", adv.name, "stu-card-paren"));
    card.appendChild(make("p", tr("อาจารย์ที่ปรึกษาประจำกลุ่ม", "Group Advisor"), "sid-mono advisor-role-mono"));

    const pillWrap = make("div", null, "s-area area-sub-pill-wrap");
