    const hint = make(
      "span",
      adv.hasPhoto ? tr("ขยายรูปอาจารย์ ↗", "Zoom Photo ↗") : tr("อาจารย์ที่ปรึกษา", "Advisor"),
      "student-quick-hint"
    );
