  function singleCsCardFitsCleanly(el) {
    if (!el || el.clientHeight <= 0 || el.clientWidth <= 0) return true;
    if (el.scrollHeight > el.clientHeight + 1) return false;
    if (el.scrollWidth > el.clientWidth + 1) return false;

    const cs = window.getComputedStyle(el);
    const padT = parseFloat(cs.paddingTop) || 0;
    const padB = parseFloat(cs.paddingBottom) || 0;
    const padR = parseFloat(cs.paddingRight) || 0;
    const bT = parseFloat(cs.borderTopWidth) || 0;
    const bB = parseFloat(cs.borderBottomWidth) || 0;
    const bR = parseFloat(cs.borderRightWidth) || 0;
    const r = el.getBoundingClientRect();
    const innerTop = r.top + bT + padT - 1.0;
    const innerBot = r.bottom - bB - padB + 1.0;
    const innerRight = r.right - bR - padR + 1.5;

    const kids = el.children;
    for (let k = 0; k < kids.length; k++) {
      const kid = kids[k];
      const kcs = window.getComputedStyle(kid);
      if (kcs.display === "none" || kcs.position === "absolute") continue;
      if (kid.scrollHeight > kid.clientHeight + 2 || kid.scrollWidth > kid.clientWidth + 2) {
        return false;
      }
      const kr = kid.getBoundingClientRect();
      if (kr.height <= 0 && kr.width <= 0) continue;
      if (kr.top < innerTop || kr.bottom > innerBot || kr.right > innerRight) {
        return false;
      }
    }
    return true;
  }

  function findMaxCsScaleForCard(el, minS, maxS, safetyFactor) {
    let lo = minS;
    let hi = maxS;
    for (let step = 0; step < 14; step++) {
      const mid = (lo + hi) * 0.5;
      el.style.setProperty("--fit-scale", mid.toFixed(4));
      if (singleCsCardFitsCleanly(el)) {
        lo = mid;
      } else {
        hi = mid;
      }
    }
    return Math.max(minS, lo * safetyFactor);
  }

  function fitConceptSummarySlideStage(sheetEl, csStage, forceRefit) {
    if (!csStage || !csStage.isConnected) return;
    csStage.style.zoom = "";

    if (!csStage._csResizeObserved && typeof ResizeObserver === "function") {
      csStage._csResizeObserved = true;
      const ro = new ResizeObserver(() => {
        if (!csStage.isConnected) {
          ro.disconnect();
          return;
        }
        if (csStage._csResizeRaf) cancelAnimationFrame(csStage._csResizeRaf);
        csStage._csResizeRaf = requestAnimationFrame(() => {
          csStage._csResizeRaf = 0;
          fitConceptSummarySlideStage(sheetEl, csStage, false);
        });
      });
      ro.observe(csStage);
    }

    const stW = csStage.clientWidth;
    const stH = csStage.clientHeight;
    if (stW < 50 || stH < 40) {
      if (!sheetEl._deferredCsFitQueued) {
        sheetEl._deferredCsFitQueued = true;
        requestAnimationFrame(() => {
          sheetEl._deferredCsFitQueued = false;
          fitConceptSummarySlideStage(sheetEl, csStage, true);
        });
      }
      return;
    }

    const isPortrait = stH > stW * 1.04;
    const csLayout = isPortrait ? (stW < 500 ? "portrait-1col" : "portrait-2col") : "landscape";
    const isFwStage = csStage.classList.contains("is-framework-visual-stage");
    const isMatrixStage = csStage.classList.contains("is-matrix-takeaway-stage");
    const fitSig = `${stW}x${stH}:${csLayout}:${isFwStage ? "fw" : isMatrixStage ? "mtx" : "bento"}`;
    if (!forceRefit && csStage._lastCsFitSig === fitSig) return;
    csStage._lastCsFitSig = fitSig;

    csStage.setAttribute("data-cs-layout", csLayout);
    csStage.classList.remove("is-cs-portrait-reflow");

    if (isMatrixStage) {
      const mWrap = csStage.querySelector(".ppt-cs-matrix-wrap");
      const mTbl = csStage.querySelector(".ppt-cs-matrix-table");
      const isNarrowStack = isPortrait || stW < 760;
      csStage.classList.toggle("is-matrix-stacked", isNarrowStack);
      if (isNarrowStack || !mWrap || !mTbl) {
        csStage.style.setProperty("--matrix-scale", "1");
        return;
      }
      csStage.style.setProperty("--matrix-scale", "1");
      const availH = mWrap.clientHeight;
      const availW = mWrap.clientWidth;
      if (availH < 60 || availW < 200) return;
      let lo = 0.66;
      let hi = 1.38;
      let best = 0.92;
      for (let it = 0; it < 9; it++) {
        const mid = (lo + hi) / 2;
        csStage.style.setProperty("--matrix-scale", mid.toFixed(4));
        if (mTbl.offsetHeight <= availH - 2 && mTbl.offsetWidth <= availW + 1) {
          best = mid;
          lo = mid;
        } else {
          hi = mid;
        }
      }
      csStage.style.setProperty("--matrix-scale", (best * 0.985).toFixed(4));
      return;
    }

    if (isFwStage) {
      const fwImg = csStage.querySelector(".ppt-cs-fw-img");
      if (fwImg && !fwImg.complete && !fwImg._csLoadWired) {
        fwImg._csLoadWired = true;
        fwImg.addEventListener("load", () => fitConceptSummarySlideStage(sheetEl, csStage, true), { once: true });
      }
      csStage.style.setProperty("--cs-hero-scale", "1");
      const topEl = csStage.querySelector(".ppt-cs-fw-top");
      const bridgeEl = csStage.querySelector(".ppt-cs-bridge");
      const chromeH = (topEl ? topEl.offsetHeight : 0) + (bridgeEl ? bridgeEl.offsetHeight : 0);
      const maxChromeRatio = stH < 440 ? 0.24 : isPortrait ? 0.36 : 0.28;
      if (chromeH > stH * maxChromeRatio && chromeH > 0) {
        const hs = Math.max(0.68, (stH * maxChromeRatio) / chromeH);
        csStage.style.setProperty("--cs-hero-scale", hs.toFixed(4));
      } else if (isPortrait && chromeH > 0 && chromeH < stH * 0.18) {
        const hs = Math.min(1.25, (stH * 0.22) / chromeH);
        csStage.style.setProperty("--cs-hero-scale", hs.toFixed(4));
      }
      return;
    }

    const heroEl = csStage.querySelector(".ppt-cs-hero");
    csStage.style.setProperty("--cs-hero-scale", "1");
    if (heroEl) {
      const hH = heroEl.offsetHeight;
      const maxHeroShare = stH < 430 ? 0.25 : isPortrait ? 0.22 : 0.26;
      const minHeroShare = isPortrait ? 0.12 : 0.15;
      if (hH > stH * maxHeroShare && hH > 0) {
        const minHeroScale = isPortrait ? 0.88 : 0.72;
        const hs = Math.max(minHeroScale, (stH * (maxHeroShare - 0.01)) / hH);
        csStage.style.setProperty("--cs-hero-scale", hs.toFixed(4));
      } else if (hH > 0 && hH < stH * minHeroShare) {
        const hs = Math.min(1.26, (stH * (minHeroShare + 0.02)) / hH);
        csStage.style.setProperty("--cs-hero-scale", hs.toFixed(4));
      }
    }

    const cards = Array.from(csStage.querySelectorAll(".ppt-cs-dim-card"));
    if (!cards.length) return;

    const minS = 0.46;
    const maxS = 2.65;
    const safetyFactor = 0.955;
    const maxSiblingSpread = 1.18;

    csStage.setAttribute("data-measuring", "1");
    const rawScales = cards.map((card) => findMaxCsScaleForCard(card, minS, maxS, safetyFactor));
    const minGroupScale = Math.min.apply(null, rawScales);
    const cap = minGroupScale * maxSiblingSpread;
    cards.forEach((card, idx) => {
      const s = Math.min(rawScales[idx], cap);
      card.style.setProperty("--fit-scale", s.toFixed(4));
    });
    csStage.removeAttribute("data-measuring");

    let anyOverflowAtMin = false;
    cards.forEach((card) => {
      let s = parseFloat(card.style.getPropertyValue("--fit-scale")) || 1;
      for (let guard = 0; guard < 5; guard++) {
        if (singleCsCardFitsCleanly(card)) break;
        s = Math.max(minS, s * 0.955);
        card.style.setProperty("--fit-scale", s.toFixed(4));
      }
      if (!singleCsCardFitsCleanly(card)) anyOverflowAtMin = true;
    });

    if (isPortrait && stW < 460) {
      const firstDef = cards[0] && cards[0].querySelector(".ppt-cs-dim-def");
      const defPx = firstDef ? parseFloat(window.getComputedStyle(firstDef).fontSize) || 12 : 12;
      if (anyOverflowAtMin || defPx < 10.5) {
        csStage.classList.add("is-cs-portrait-reflow");
        cards.forEach((card) => card.style.setProperty("--fit-scale", "1.05"));
      }
    }
  }

  function autoFitSingleSheetBoxes(sheetEl, forceBoxRefit) {
    if (!sheetEl || !sheetEl.isConnected) return;
    const isHandout = sheetEl.classList.contains("is-handout-sheet");
    const isRespSlide = sheetEl.classList.contains("is-responsive-slide");
    const isAutoHoriz = sheetEl.classList.contains("is-auto-horiz-split");
    const isCompactResp =
      isRespSlide && (isAutoHoriz || sheetEl.offsetWidth < 820 || sheetEl.offsetHeight < 500);
    const fitZ = isCompactResp ? 0.96 : Number(sheetEl.dataset.pptFitZoom) || 0.92;

    const isOpeningSlide = sheetEl.classList.contains("is-layout-opening-kahoot");
    let isStackedOpeningStage = false;
    if (isOpeningSlide && !isHandout) {
      const okStage = sheetEl.querySelector(".ppt-opening-kahoot-stage");
      const okLeft = okStage && okStage.querySelector(".ppt-ok-col-qr");
      const okRight = okStage && okStage.querySelector(".ppt-ok-right");
      if (okLeft) okLeft.style.zoom = "";
      if (okRight) okRight.style.zoom = "";
      if (okStage) {
        const stW = sheetEl.offsetWidth || okStage.clientWidth || 0;
        const stH = sheetEl.offsetHeight || okStage.clientHeight || 0;
        const isCrampedStage = (stW > 0 && stW < 720) || (stH > 0 && stH < 430);
        const isNarrowStage = stW > 0 && stW < 680;
        okStage.classList.toggle("is-ok-compact-stage", isCrampedStage);
        okStage.classList.toggle("is-ok-1col-stage", isNarrowStage);
        if (isCrampedStage || (okLeft && okRight && okRight.offsetTop > okLeft.offsetTop + 20)) {
          isStackedOpeningStage = true;
        }
      }
    }

    if (
      sheetEl.classList.contains("is-layout-concept-summary") &&
      !sheetEl.classList.contains("is-hidden-slide-sheet") &&
      !isHandout
    ) {
      const csStage = sheetEl.querySelector(".ppt-concept-summary-stage");
      if (csStage) {
        fitConceptSummarySlideStage(sheetEl, csStage, Boolean(forceBoxRefit));
      }
      return;
    }

    const isPureScenarioSlide =
      sheetEl.classList.contains("is-layout-case-scenario") ||
      sheetEl.classList.contains("is-layout-scenario");
    const isLiveSheetSlide = sheetEl.classList.contains("is-layout-live-sheet");
    const isFullSingleSlide =
      isPureScenarioSlide ||
      sheetEl.classList.contains("is-layout-sheet") ||
      sheetEl.classList.contains("is-layout-key-full");

    sheetEl.querySelectorAll(".hsd-box-zoom-body").forEach((boxEl) => {
      const side = boxEl.getAttribute("data-box-side") || "right";
      const isLeft = side === "left";
      const isAuto = isLeft ? state.hsdLeftAutoFit !== false : state.hsdRightAutoFit !== false;
      const manualPct = (isLeft ? state.hsdLeftFontPct : state.hsdRightFontPct) || 100;
      const paneEl = boxEl.closest(".hsd-slide-left, .hsd-slide-right, .hsd-key-slide-stage, .is-ok-autofit-pane");
      const dohShells = Array.from(boxEl.querySelectorAll(".doh-diagram-shell")).filter(
        (sh) => !sh.hidden && !sh.closest("[hidden]")
      );
      const hasDohShell = dohShells.length > 0;
      const autoTextareas = Array.from(boxEl.querySelectorAll("textarea"));
      const syncAllBoxTextareas = () => {
        autoTextareas.forEach((t) => {
          if (typeof t._fitDohTaNow === "function") t._fitDohTaNow();
          if (typeof t._fitWsTaNow === "function") t._fitWsTaNow();
        });
      };
      const setBoxZoom = (zNum) => {
        boxEl.style.zoom = zNum.toFixed(4);
        if (hasDohShell) {
          dohShells.forEach((sh) => syncDohShellScale(sh, true));
        }
        if (autoTextareas.length) {
          syncAllBoxTextareas();
        }
      };

      if (isOpeningSlide && isStackedOpeningStage) {
        boxEl._lastFitSig = "";
        if (!isAuto) {
          setBoxZoom(manualPct / 100);
          boxEl.dataset.effectivePct = String(manualPct);
          sheetEl.querySelectorAll(`[data-box-pct="${side}"]`).forEach((b) => {
            b.textContent = `${manualPct}%`;
          });
        } else {
          setBoxZoom(1);
          boxEl.dataset.effectivePct = "100";
          sheetEl.querySelectorAll(`[data-box-pct="${side}"]`).forEach((b) => {
            b.textContent = "Auto 100%";
          });
        }
        return;
      }

      if (!isAuto) {
        boxEl._lastFitSig = "";
        if (paneEl) {
          paneEl.style.overflowY = "auto";
          paneEl.style.overflowX = "auto";
        }
        setBoxZoom((manualPct / 100) * fitZ);
        if (hasDohShell) {
          dohShells.forEach((sh) => {
            if (typeof sh._syncDohScale === "function") sh._syncDohScale(true, false);
          });
        }
        boxEl.dataset.effectivePct = String(manualPct);
        sheetEl.querySelectorAll(`[data-box-pct="${side}"]`).forEach((b) => {
          b.textContent = `${manualPct}%`;
        });
        return;
      }

      if (!paneEl || paneEl.hidden) {
        boxEl._lastFitSig = "";
        setBoxZoom(fitZ);
        boxEl.dataset.effectivePct = "100";
        sheetEl.querySelectorAll(`[data-box-pct="${side}"]`).forEach((b) => {
          b.textContent = "Auto 100%";
        });
        return;
      }

      const pOffW = paneEl.offsetWidth;
      const pOffH = paneEl.offsetHeight;
      if (pOffH < 36 || pOffW < 50) {
        setBoxZoom(fitZ);
        if (!sheetEl._deferredFitQueued) {
          sheetEl._deferredFitQueued = true;
          requestAnimationFrame(() => {
            sheetEl._deferredFitQueued = false;
            autoFitSingleSheetBoxes(sheetEl, true);
          });
        }
        return;
      }

      if (!isHandout && document.activeElement && boxEl.contains(document.activeElement) && isEditableElementFocusedInOverlay()) {
        const envTyping = getPptViewportEnv();
        if (envTyping.isKbdOpen && (envTyping.isCoarse || envTyping.w <= 960 || envTyping.h < 520)) {
          if (boxEl.style.zoom !== "1") {
            boxEl._lastFitSig = "";
            boxEl.style.zoom = "1";
            if (hasDohShell) {
              dohShells.forEach((sh) => syncDohShellScale(sh, true));
            }
            if (autoTextareas.length) {
              syncAllBoxTextareas();
            }
          }
          paneEl.style.overflowX = "hidden";
        }
        paneEl.style.overflowY = "auto";
        if (hasDohShell) {
          dohShells.forEach((sh) => {
            if (typeof sh._syncDohScale === "function") sh._syncDohScale(true, false);
            else syncDohShellScale(sh, true);
          });
        }
        if (autoTextareas.length) {
          syncAllBoxTextareas();
        }
        return;
      }

      const okItemSig = isOpeningSlide ? `:ok${boxEl.querySelectorAll(".ppt-ok-stu-chip, .ppt-ok-stu-lobby-btn").length}` : "";
      const fitSig = `${pOffW}x${pOffH}@${fitZ.toFixed(4)}:${isRespSlide ? "rs" : "16x9"}:${isCompactResp ? "c" : "d"}:${isLiveSheetSlide ? "live" : "std"}:${hasDohShell ? "doh" : "tbl"}${okItemSig}`;
      if (!forceBoxRefit && boxEl._lastFitSig === fitSig) {
        if (hasDohShell) {
          dohShells.forEach((sh) => {
            if (typeof sh._syncDohScale === "function") sh._syncDohScale(false, false);
          });
        }
        return;
      }

      const prevScrollTop = paneEl.scrollTop;
      const prevScrollLeft = paneEl.scrollLeft;

      // Lock overflow hidden (via .is-autofit-measuring to override !important pane scroll CSS) so OS scrollbars never toggle clientWidth/clientHeight mid-search
      paneEl.classList.add("is-autofit-measuring");
      paneEl.style.overflowY = "hidden";
      paneEl.style.overflowX = "hidden";
      paneEl.scrollTop = 0;
      paneEl.scrollLeft = 0;

      let chosenPct = 100;
      const fitsCleanly = () =>
        paneEl.scrollHeight <= paneEl.clientHeight + (isHandout ? 2 : 0) &&
        boxEl.scrollWidth <= boxEl.clientWidth + 5;

      try {
        setBoxZoom(fitZ);

        const minAutoPct = isHandout
          ? 24
          : isOpeningSlide
          ? 46
          : hasDohShell
          ? pOffW > pOffH
            ? 28
            : 64
          : isLiveSheetSlide
          ? 86
          : isCompactResp
          ? 100
          : isRespSlide
          ? 82
          : 64;
        const maxAutoPct = isHandout
          ? 118
          : isOpeningSlide
          ? 215
          : isLiveSheetSlide && !hasDohShell
          ? 100
          : hasDohShell && pOffW < 760
          ? 104
          : isCompactResp
          ? isFullSingleSlide
            ? 168
            : 136
          : isPureScenarioSlide
          ? 235
          : isFullSingleSlide
          ? 192
          : 172;

        if (!fitsCleanly()) {
          if (minAutoPct >= 100) {
            chosenPct = 100;
          } else {
            let lo = minAutoPct;
            let hi = 99;
            let best = minAutoPct;
            while (lo <= hi) {
              const mid = Math.floor((lo + hi) / 2);
              setBoxZoom((mid / 100) * fitZ);
              if (fitsCleanly()) {
                best = mid;
                lo = mid + 1;
              } else {
                hi = mid - 1;
              }
            }
            chosenPct = best;
            setBoxZoom((chosenPct / 100) * fitZ);
            if (isHandout) {
              while (chosenPct > 18 && !fitsCleanly()) {
                chosenPct -= 1;
                setBoxZoom((chosenPct / 100) * fitZ);
              }
            }
          }
        } else {
          const pRect = paneEl.getBoundingClientRect();
          const bRect = boxEl.getBoundingClientRect();
          const usedRatio = pRect.height > 0 ? (bRect.bottom - pRect.top) / pRect.height : 1;
          if (usedRatio > 0 && usedRatio < 0.90 && maxAutoPct > 100) {
            let lo = 101;
            let hi = maxAutoPct;
            let bestUp = 100;
            while (lo <= hi) {
              const mid = Math.floor((lo + hi) / 2);
              setBoxZoom((mid / 100) * fitZ);
              if (fitsCleanly()) {
                const pR2 = paneEl.getBoundingClientRect();
                const bR2 = boxEl.getBoundingClientRect();
                const ratio2 = pR2.height > 0 ? (bR2.bottom - pR2.top) / pR2.height : 1;
                if (ratio2 <= 0.95) {
                  bestUp = mid;
                  lo = mid + 1;
                } else {
                  hi = mid - 1;
                }
              } else {
                hi = mid - 1;
              }
            }
            chosenPct = bestUp;
          }
        }

        setBoxZoom((chosenPct / 100) * fitZ);
        if (isHandout) {
          while (chosenPct > 14 && !fitsCleanly()) {
            chosenPct -= 1;
            setBoxZoom((chosenPct / 100) * fitZ);
          }
        }
      } finally {
        paneEl.classList.remove("is-autofit-measuring");
      }

      if (!isHandout && (isLiveSheetSlide || isRespSlide || !fitsCleanly())) {
        paneEl.style.overflowY = "auto";
      }

      if (hasDohShell) {
        dohShells.forEach((sh) => {
          if (typeof sh._syncDohScale === "function") sh._syncDohScale(true, false);
        });
      }

      boxEl._lastFitSig = fitSig;
      boxEl.dataset.effectivePct = String(chosenPct);
      paneEl.scrollTop = Math.min(prevScrollTop, Math.max(0, paneEl.scrollHeight - paneEl.clientHeight));
      paneEl.scrollLeft = prevScrollLeft;
      sheetEl.querySelectorAll(`[data-box-pct="${side}"]`).forEach((b) => {
        b.textContent = `Auto ${chosenPct}%`;
      });
    });

    if (typeof sheetEl._redrawConceptLines === "function") {
      requestAnimationFrame(() => sheetEl._redrawConceptLines());
    }
  }

  function applySlideBoxesZoom(rootEl) {
    const scope = rootEl || document;
    scope.querySelectorAll(".ppt-slide-sheet").forEach((sheetEl) => {
      autoFitSingleSheetBoxes(sheetEl, true);
    });
  }

  function scheduleStabilizedSlideFit(stageEl, sheetEl, useZoomState) {
    fitSlideSheetToStage(stageEl, sheetEl, useZoomState, true);
    requestAnimationFrame(() => {
      if (sheetEl && sheetEl.isConnected) {
        fitSlideSheetToStage(stageEl, sheetEl, useZoomState, true);
      }
    });
    if (document.fonts && document.fonts.ready && typeof document.fonts.ready.then === "function") {
      document.fonts.ready.then(() => {
        if (sheetEl && sheetEl.isConnected) {
          fitSlideSheetToStage(stageEl, sheetEl, useZoomState, true);
        }
      });
    }
  }

  function buildBoxFontSizeCtrlDOM(side) {
    const isLeft = side === "left";
    const ctrl = make("div", null, "hsd-box-font-ctrl hsd-no-print");
    ctrl.addEventListener("pointerdown", (ev) => ev.stopPropagation());

    const getDisplayedPct = () => {
      const hostSheet =
        ctrl.closest(".ppt-slide-sheet") ||
        document.querySelector("#pptPresentationOverlay:not([hidden]) .ppt-slide-sheet") ||
        document.querySelector(".ppt-slide-sheet");
      const box = hostSheet && hostSheet.querySelector(`.hsd-box-zoom-body[data-box-side="${side}"]`);
      if (box && box.dataset.effectivePct) {
        return Number(box.dataset.effectivePct) || 100;
      }
      return (isLeft ? state.hsdLeftFontPct : state.hsdRightFontPct) || 100;
    };
    const applyManualPct = (nextVal) => {
      const clamped = Math.max(50, Math.min(260, Math.round(nextVal)));
      if (isLeft) {
        state.hsdLeftAutoFit = false;
        state.hsdLeftFontPct = clamped;
        try {
          localStorage.setItem("racm303_hsd_lfont_auto", "0");
          localStorage.setItem("racm303_hsd_lfont_v2", String(clamped));
        } catch (_) {}
      } else {
        state.hsdRightAutoFit = false;
        state.hsdRightFontPct = clamped;
        try {
          localStorage.setItem("racm303_hsd_rfont_auto", "0");
          localStorage.setItem("racm303_hsd_rfont_v2", String(clamped));
        } catch (_) {}
      }
      applySlideBoxesZoom(document);
      broadcastPptPresentationState();
    };

    const resetToAutoFit = () => {
      if (isLeft) {
        state.hsdLeftAutoFit = true;
        state.hsdLeftFontPct = 100;
        try {
          localStorage.setItem("racm303_hsd_lfont_auto", "1");
          localStorage.setItem("racm303_hsd_lfont_v2", "100");
        } catch (_) {}
      } else {
        state.hsdRightAutoFit = true;
        state.hsdRightFontPct = 100;
        try {
          localStorage.setItem("racm303_hsd_rfont_auto", "1");
          localStorage.setItem("racm303_hsd_rfont_v2", "100");
        } catch (_) {}
      }
      applySlideBoxesZoom(document);
      broadcastPptPresentationState();
    };

    const minusBtn = make("button", "ก−", "hsd-box-font-btn");
    minusBtn.type = "button";
    minusBtn.title = "ลดขนาดตัวอักษรเฉพาะในกล่องนี้";
    minusBtn.addEventListener("click", (ev) => {
      ev.stopPropagation();
      applyManualPct(getDisplayedPct() - 8);
    });

    const isAutoNow = isLeft ? state.hsdLeftAutoFit !== false : state.hsdRightAutoFit !== false;
    const initLabel = isAutoNow
      ? "Auto 100%"
      : `${(isLeft ? state.hsdLeftFontPct : state.hsdRightFontPct) || 100}%`;
    const pctBtn = make("button", initLabel, "hsd-box-font-btn is-pct");
    pctBtn.type = "button";
    pctBtn.setAttribute("data-box-pct", side);
    pctBtn.title = "คลิกเพื่อปรับขนาดตัวอักษรให้พอดีกล่องอัตโนมัติ (Automatic Optimized Font Size)";
    pctBtn.addEventListener("click", (ev) => {
      ev.stopPropagation();
      resetToAutoFit();
    });

    const plusBtn = make("button", "ก+", "hsd-box-font-btn");
    plusBtn.type = "button";
    plusBtn.title = "เพิ่มขนาดตัวอักษรเฉพาะในกล่องนี้";
    plusBtn.addEventListener("click", (ev) => {
      ev.stopPropagation();
      applyManualPct(getDisplayedPct() + 8);
    });

    ctrl.append(minusBtn, pctBtn, plusBtn);
    return ctrl;
  }

  function buildPaneBarQuickActionsDOM(boxSide, layout, cur) {
    const isSplit =
      layout === "split-key" ||
      layout === "split-key-all" ||
      layout === "split-sheet" ||
      layout === "split-concept";
    const isHoriz = state.hsdSplitOrient === "horizontal";
    const wrap = make("div", null, "hsd-pane-bar-actions hsd-no-print");
    wrap.addEventListener("pointerdown", (ev) => ev.stopPropagation());

    if (layout === "split-concept" && boxSide === "left" && ROLE === "faculty") {
      const lineToggleBtn = make(
        "button",
        state.hsdShowConceptLines !== false ? "🔗 เส้นเชื่อม: เปิด" : "🔗 เส้นเชื่อม: ปิด",
        `hsd-pane-vis-btn is-concept-line-btn${state.hsdShowConceptLines !== false ? " is-active" : ""}`
      );
      lineToggleBtn.type = "button";
      lineToggleBtn.title = "เปิด/ปิดเส้นเชื่อม Highlight จากโจทย์ไปยังคำตอบใน Answer Key";
      lineToggleBtn.addEventListener("click", (ev) => {
        ev.stopPropagation();
        state.hsdShowConceptLines = state.hsdShowConceptLines === false;
        renderHsDiscussionView();
        broadcastPptPresentationState();
      });
      wrap.appendChild(lineToggleBtn);
    }

    if ((layout === "key-full" || layout === "split-key-all" || layout === "split-key") && boxSide === "right" && ROLE === "faculty" && cur && cur.qObj) {
      const totalK = getHsQuestionKeyTotalSteps(cur.qObj.id);
      if (totalK > 0 && layout === "key-full") {
        const curK = getEffectiveHsKeyStep(cur.qObj.id);
        const stepKeyBtn = make(
          "button",
          curK >= totalK ? "🙈 ซ่อนเฉลยทีละข้อ" : `👁 เปิดทีละข้อ (${curK}/${totalK})`,
          "hsd-pane-vis-btn is-orient-btn"
        );
        stepKeyBtn.type = "button";
        stepKeyBtn.addEventListener("click", (ev) => {
          ev.stopPropagation();
          if (curK >= totalK) stepHsAnswerKeyClicker(0, "hide");
          else stepHsAnswerKeyClicker(1);
        });
        wrap.appendChild(stepKeyBtn);
      }
    }

    if (isSplit) {
      if (boxSide === "left") {
        const orientBtn = make(
          "button",
          isHoriz ? "◫ แนวตั้ง" : "⬒ แนวนอน",
          "hsd-pane-vis-btn is-orient-btn"
        );
        orientBtn.type = "button";
        orientBtn.title = isHoriz
          ? "สลับเป็นการแบ่งครึ่งแนวตั้ง (ซ้าย–ขวา)"
          : "สลับเป็นการแบ่งครึ่งแนวนอน (บน–ล่าง)";
        orientBtn.addEventListener("click", (ev) => {
          ev.stopPropagation();
          setHsdSplitOrientation(isHoriz ? "vertical" : "horizontal");
        });
        wrap.appendChild(orientBtn);
      }

      const hideBoxBtn = make(
        "button",
        boxSide === "left"
          ? "🙈 ซ่อนโจทย์"
          : ROLE === "faculty" && (layout === "split-key" || layout === "split-key-all" || layout === "split-concept")
          ? "🙈 ซ่อนฝั่งคำตอบ"
          : "🙈 ซ่อนใบงาน",
        "hsd-pane-vis-btn is-hide-btn"
      );
      hideBoxBtn.type = "button";
      hideBoxBtn.title = boxSide === "left"
        ? "ซ่อนกล่องสถานการณ์เพื่อขยายกล่องคำถาม+คำตอบเต็มสไลด์"
        : "ซ่อนกล่องคำตอบเพื่อขยายกล่องสถานการณ์เต็มสไลด์";
      hideBoxBtn.addEventListener("click", (ev) => {
        ev.stopPropagation();
        toggleHsdBoxVisibility(boxSide, false);
      });
      wrap.appendChild(hideBoxBtn);
    } else if (layout === "case-scenario") {
      const nextToSheetBtn = make(
        "button",
        "ถัดไป: คำถาม & Answer Sheet →",
        "hsd-pane-vis-btn is-unhide-btn"
      );
      nextToSheetBtn.type = "button";
      nextToSheetBtn.addEventListener("click", (ev) => {
        ev.stopPropagation();
        stepHsQuestionSlide(1);
      });
      wrap.appendChild(nextToSheetBtn);
    } else if (layout === "scenario") {
      const inlineQBtn = make(
        "button",
        state.hsdHideInlineQInScen ? "👁 แสดงคำถามหัวสไลด์" : "🙈 ซ่อนคำถามหัวสไลด์",
        "hsd-pane-vis-btn"
      );
      inlineQBtn.type = "button";
      inlineQBtn.addEventListener("click", (ev) => {
        ev.stopPropagation();
        state.hsdHideInlineQInScen = !state.hsdHideInlineQInScen;
        markSlideBoxesAutoOptimize("left");
        renderHsDiscussionView();
        broadcastPptPresentationState();
      });
      wrap.appendChild(inlineQBtn);

      const unhideRightBtn = make(
        "button",
        ROLE === "faculty" ? "👁 แสดงกล่องคำถาม+คำตอบคู่กัน" : "👁 แสดงกล่องใบงานคู่กัน",
        "hsd-pane-vis-btn is-unhide-btn"
      );
      unhideRightBtn.type = "button";
      unhideRightBtn.addEventListener("click", (ev) => {
        ev.stopPropagation();
        toggleHsdBoxVisibility("right", true);
      });
      wrap.appendChild(unhideRightBtn);
    } else {
      const unhideLeftBtn = make(
        "button",
        layout === "key-full" ? "👁 แสดง Highlight โจทย์คู่กัน" : "👁 แสดงโจทย์ประกบคู่กัน",
        "hsd-pane-vis-btn is-unhide-btn"
      );
      unhideLeftBtn.type = "button";
      unhideLeftBtn.addEventListener("click", (ev) => {
        ev.stopPropagation();
        toggleHsdBoxVisibility("left", true);
      });
      wrap.appendChild(unhideLeftBtn);
    }

    wrap.appendChild(buildBoxFontSizeCtrlDOM(boxSide));
    return wrap;
  }

  function buildPptSessionDeckTabsDOM(activeModId) {
    const bar = make("div", null, "ppt-session-deck-bar hsd-no-print");
    bar.appendChild(make("span", "📊 เลือกไฟล์สไลด์ประจำคาบ (PPT แยกแต่ละคาบ):", "ppt-sdb-label"));
    const pills = make("div", null, "ppt-sdb-pills");
    (HSD_DATA.modules || []).forEach((m) => {
      const isAct = m.id === activeModId;
      const caseCnt = (HSD_DATA.cases || []).filter((c) => c.module === m.id).length;
      const qCnt = (HSD_DATA.cases || [])
        .filter((c) => c.module === m.id)
        .reduce((acc, c) => acc + ((c.questions && c.questions.length) || 0), 0);
      const btn = make(
        "button",
        `คาบ ${m.code}.pptx (${qCnt} ข้อ)`,
        `ppt-sdb-pill${isAct ? " is-active" : ""}`
      );
      btn.type = "button";
      btn.dataset.pptDeckMod = m.id;
      btn.setAttribute("aria-pressed", isAct ? "true" : "false");
      btn.title = `คาบ ${m.code}: ${m.title} — ${m.scheduleDate} (${m.discTime}) · ${caseCnt} กรณีศึกษา`;
      btn.addEventListener("click", () => selectHsSessionDeck(m.id));
      pills.appendChild(btn);
    });
    bar.appendChild(pills);
    return bar;
  }

  function populateOpeningKahootRosterCardDOM(cardEl) {
    if (!cardEl) return;
    cardEl.classList.add("is-ok-autofit-pane");
    const isInteractive = cardEl.dataset.pptOkInteractive === "1" && !state.isPptSlideSharePopup;
    const st = getKahootRoomRosterStatus();
    const joinedSet = new Set(
      (st.joinedList || [])
        .map((p) => String(p.studentId || "").trim())
        .filter(Boolean)
    );
    cardEl.replaceChildren();

    const rHead = make("div", null, "ppt-ok-roster-head");
    const rTitleWrap = make("div", null, "ppt-ok-roster-title-wrap");
    rTitleWrap.appendChild(
      make(
        "span",
        `🟢 Live Lobby ห้อง ${st.roomDef.roomCode} · ออนไลน์ ${st.joinedCount}/${st.totalExpected} คน`,
        "ppt-ok-roster-count"
      )
    );
    rHead.appendChild(rTitleWrap);

    if (isInteractive) {
      const rHeadActions = make("div", null, "ppt-ok-roster-head-actions hsd-no-print");
      if (
        ROLE === "faculty" &&
        window.RACM_HSD_ROOM_QR &&
        typeof window.RACM_HSD_ROOM_QR.openResetCheckinConfirmModal === "function"
      ) {
        const rstOkBtn = make("button", "🔄 ล้าง Check-in ใหม่", "ppt-ok-reset-checkin-btn");
        rstOkBtn.type = "button";
        rstOkBtn.title = `ล้าง Cache การ Check-in ห้อง ${st.roomDef.roomCode} ให้นักศึกษาสแกน QR / กรอกรหัส 3 ตัวท้ายใหม่ทั้งหมด`;
        rstOkBtn.addEventListener("click", () => {
          const effMod = cardEl.dataset.pptOkMod || (state.hsdModule !== "ALL" ? state.hsdModule : "HS1");
          window.RACM_HSD_ROOM_QR.openResetCheckinConfirmModal(effMod, st.roomId, () => {
            syncLiveConnectionAndPresenceDOM();
          });
        });
        rHeadActions.appendChild(rstOkBtn);
      }
      if (typeof openHsdKahootLobbyModal === "function") {
        const fullLobbyBtn = make("button", "ดูสถานะ Live Lobby ↗", "btn sm");
        fullLobbyBtn.type = "button";
        fullLobbyBtn.addEventListener("click", () => openHsdKahootLobbyModal());
        rHeadActions.appendChild(fullLobbyBtn);
      }
      rHeadActions.appendChild(buildBoxFontSizeCtrlDOM("right"));
      rHead.appendChild(rHeadActions);
    }
    cardEl.appendChild(rHead);

    const rosterZoomBody = make("div", null, "hsd-box-zoom-body is-ok-roster-zoom-body");
    rosterZoomBody.dataset.boxSide = "right";

    const grid = make("div", null, "ppt-ok-roster-grid");
    (st.assigned || []).forEach((s) => {
      const sid = String(s.id || "");
      const joined = joinedSet.has(sid);
      const shortCode = sid.slice(-3);
      const dispName = s.nickname ? `${s.nickname}` : String(s.name || s.fullName || "").split(" ")[0];
      const chip = make("div", null, `ppt-ok-stu-chip${joined ? " is-joined" : ""}`);
      chip.title = `${sid} · ${s.fullName}${joined ? " (ออนไลน์ในห้องขณะนี้)" : " (ยังไม่ออนไลน์ / ออกจากห้องไปแล้ว)"}`;
      chip.innerHTML = `<span class="ppt-ok-stu-check">${joined ? "✓" : "•"}</span><span class="ppt-ok-stu-label">${escapeHtml(shortCode)} ${escapeHtml(dispName)}</span>`;
      grid.appendChild(chip);
    });

    // Also render any guest students online in this room
    const assignedIds = new Set((st.assigned || []).map((s) => String(s.id)));
    (st.joinedList || []).forEach((p) => {
      const sid = String(p.studentId || "");
      if (sid && assignedIds.has(sid)) return;
      const sCode = p.shortNo || (sid ? sid.slice(-3) : "");
      const gDisp = p.nickname || String(p.fullName || "นักศึกษา").split(" ")[0];
      const chip = make("div", null, "ppt-ok-stu-chip is-joined");
      chip.title = `${sid} · ${p.fullName || gDisp} (ออนไลน์)`;
      chip.innerHTML = `<span class="ppt-ok-stu-check">✓</span><span class="ppt-ok-stu-label">${escapeHtml(sCode)} ${escapeHtml(gDisp)}</span>`;
      grid.appendChild(chip);
    });

    rosterZoomBody.appendChild(grid);
    cardEl.appendChild(rosterZoomBody);
  }

  function refreshOpeningKahootSlideRosterDOM() {
    document.querySelectorAll("[data-ppt-ok-roster-mount='1']").forEach((el) => {
      populateOpeningKahootRosterCardDOM(el);
      const parentSheet = el.closest(".ppt-slide-sheet");
      if (parentSheet) {
        autoFitSingleSheetBoxes(parentSheet, true);
      }
    });
    document.querySelectorAll("[data-hsd-checkin-card='1']").forEach((el) => {
      if (typeof el._syncUI === "function") el._syncUI();
    });
    document.querySelectorAll("[data-hsd-checkin-status-panel='1']").forEach((el) => {
      if (typeof el._syncStatus === "function") el._syncStatus();
    });
    document.querySelectorAll("[data-ppt-ok-room-pill]").forEach((pill) => {
      const gNum = Number(pill.dataset.pptOkRoomPill) || 1;
      const rSt = getKahootRoomRosterStatus(gNum);
      let cntEl = pill.querySelector(".ppt-ok-rp-cnt");
      if (rSt.joinedCount > 0) {
        if (!cntEl) {
          cntEl = make("span", String(rSt.joinedCount), "ppt-ok-rp-cnt");
          pill.appendChild(cntEl);
        } else {
          cntEl.textContent = String(rSt.joinedCount);
        }
      } else if (cntEl) {
        cntEl.remove();
      }
    });
  }

