  function applyThemeMode(theme) {
    state.theme = theme === "dark" ? "dark" : "light";
    document.documentElement.setAttribute("data-theme", state.theme);
    try {
      localStorage.setItem("racm303_theme", state.theme);
    } catch (_) {}
    syncPreferenceButtonsUI();
    if (typeof broadcastPptPresentationState === "function") {
      broadcastPptPresentationState();
    }
  }

  function initLanguageAndThemeControls() {
    document.documentElement.setAttribute("data-theme", state.theme);
    document.documentElement.setAttribute("data-lang", state.lang);
    document.documentElement.lang = state.lang;
    syncPreferenceButtonsUI();

    const langBtn = $("langToggleBtn");
    if (langBtn) {
      langBtn.addEventListener("click", () => {
        const nextLang = state.lang === "th" ? "en" : "th";
        try {
          localStorage.setItem("racm303_lang", nextLang);
        } catch (_) {}
        applyStaticDomLanguage(nextLang);
        if (LIVE && $("hsdLiveClassroomBar") && $("hsdTimerWidget")) {
          renderHsLiveClassroomBar();
        }
        if (state.activeTab === "schedule") renderScheduleCurrent();
        else if (state.activeTab === "fieldwork") renderFieldworkView();
        else if (state.activeTab === "discussion") renderDiscussionView();
        else if (state.activeTab === "hs-discussion") renderHsDiscussionView();
        else if (state.activeTab === "textbooks") renderTextbookReader();
        else if (state.activeTab === "systems-forum") renderSystemsForumView();
        if (typeof renderRoleConcierge === "function") renderRoleConcierge();
      });
    }

    const themeBtn = $("themeToggleBtn");
    if (themeBtn) {
      themeBtn.addEventListener("click", (ev) => {
        const pickedEl = ev.target && ev.target.closest ? ev.target.closest("[data-theme-pick]") : null;
        const pickedTheme = pickedEl ? pickedEl.getAttribute("data-theme-pick") : "";
        if (pickedTheme && pickedTheme !== state.theme) {
          applyThemeMode(pickedTheme);
        } else {
          applyThemeMode(state.theme === "dark" ? "light" : "dark");
        }
      });
    }
  }

  /* ---------- Faculty Teacher Guides & Original Links (#panel-faculty-docs) ---------- */
  function resolveFacultyGuideDocIdForModule(modCode) {
    const clean = /^(HS[1-6]|ST1)$/i.test(String(modCode || "")) ? String(modCode).toUpperCase() : "HS1";
    const docs = (typeof FACULTY !== "undefined" && FACULTY && FACULTY.docs) || [];
    const matched = docs.find(
      (d) =>
        String(d.id || "").toUpperCase().startsWith(clean) ||
        String(d.title || "").toUpperCase().startsWith(clean)
    );
    return matched ? matched.id : (docs[0] && docs[0].id) || "hs-disc-teacher-key";
  }

  function openFacultyGuideForHsModule(modCode) {
    const clean = /^(HS[1-6]|ST1)$/i.test(String(modCode || "")) ? String(modCode).toUpperCase() : "HS1";
    state.activeHsModule = clean;
    state.facultySub = "guides";
    state.activeFacultyDocId = resolveFacultyGuideDocIdForModule(clean);
    document.querySelectorAll("[data-fac-sub]").forEach((b) =>
      b.setAttribute("aria-pressed", b.dataset.facSub === "guides" ? "true" : "false")
    );
    switchTab("faculty-docs");
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  /* ---------- Faculty Print-out PDF Binder Hub (6 Core Sections + 9 Site Advisor Packets) ---------- */
  function openFacultyPrintoutHub() {
    state.facPrintHubCollapsed = false;
    switchTab("manual");
    requestAnimationFrame(() => {
      const mount = $("facultyPrintoutHubMount");
      if (mount) mount.scrollIntoView({ behavior: "smooth", block: "start" });
      else window.scrollTo({ top: 0, behavior: "smooth" });
    });
  }

